package de.hamedtanha.servertoolkit.feature.ssh.data.service

import java.nio.charset.StandardCharsets
import java.util.Base64

/**
 * Test-only private-key fixtures generated exclusively for automated parsing verification.
 *
 * These keys have no operational use, their public halves are not trusted anywhere, and they must
 * never be reused outside tests. Encoding avoids committing raw PEM private-key blocks.
 */
internal object SshPrivateKeyTestFixtures {

    const val PASSPHRASE: String = "servertoolkit-test-only"

    fun openSshEd25519Unencrypted(): ByteArray {
        return decode(OPENSSH_ED25519_UNENCRYPTED_BASE64)
    }

    fun openSshEd25519Encrypted(): ByteArray {
        return decode(OPENSSH_ED25519_ENCRYPTED_BASE64)
    }

    fun openSshRsaUnencrypted(): ByteArray {
        return decode(OPENSSH_RSA_UNENCRYPTED_BASE64)
    }

    fun openSshRsaEncrypted(): ByteArray {
        return decode(OPENSSH_RSA_ENCRYPTED_BASE64)
    }

    fun openSshEcdsaUnencrypted(): ByteArray {
        return decode(OPENSSH_ECDSA_UNENCRYPTED_BASE64)
    }

    fun openSshEd25519EncryptedWithBcryptRounds(
        rounds: Long,
    ): ByteArray {
        require(rounds in 0L..UINT32_MAX)

        return rewriteOpenSshBcryptRounds(
            privateKey = openSshEd25519Encrypted(),
            rounds = rounds,
        )
    }

    fun pkcs8RsaUnencrypted(): ByteArray {
        return decode(PKCS8_RSA_UNENCRYPTED_BASE64)
    }

    fun pkcs8RsaEncrypted(): ByteArray {
        return decode(PKCS8_RSA_ENCRYPTED_BASE64)
    }

    private fun rewriteOpenSshBcryptRounds(
        privateKey: ByteArray,
        rounds: Long,
    ): ByteArray {
        val pem = String(privateKey, StandardCharsets.UTF_8)
        val encodedPayload = pem
            .lineSequence()
            .filterNot { line -> line.startsWith(PEM_BOUNDARY_PREFIX) }
            .joinToString(separator = "")

        val decodedKey = Base64.getDecoder().decode(encodedPayload)

        try {
            var offset = OPENSSH_AUTH_MAGIC_SIZE
            offset = skipSshString(decodedKey, offset)
            offset = skipSshString(decodedKey, offset)

            val kdfOptionsLength = readUInt32(decodedKey, offset).toInt()
            val kdfOptionsStart = offset + UINT32_SIZE_BYTES
            val kdfOptionsEnd = kdfOptionsStart + kdfOptionsLength

            require(kdfOptionsEnd <= decodedKey.size)

            val saltLength = readUInt32(decodedKey, kdfOptionsStart).toInt()
            val roundsOffset =
                kdfOptionsStart + UINT32_SIZE_BYTES + saltLength

            require(roundsOffset + UINT32_SIZE_BYTES <= kdfOptionsEnd)

            writeUInt32(
                bytes = decodedKey,
                offset = roundsOffset,
                value = rounds,
            )

            val encoded = Base64.getMimeEncoder(
                PEM_LINE_LENGTH,
                byteArrayOf('\n'.code.toByte()),
            ).encodeToString(decodedKey)

            return buildString {
                append(PEM_BOUNDARY_PREFIX)
                append("BEGIN ")
                append(OPENSSH_PRIVATE_KEY_LABEL)
                appendLine(PEM_BOUNDARY_SUFFIX)
                appendLine(encoded)
                append(PEM_BOUNDARY_PREFIX)
                append("END ")
                append(OPENSSH_PRIVATE_KEY_LABEL)
                appendLine(PEM_BOUNDARY_SUFFIX)
            }.toByteArray(StandardCharsets.UTF_8)
        } finally {
            decodedKey.fill(0)
            privateKey.fill(0)
        }
    }

    private fun skipSshString(
        bytes: ByteArray,
        offset: Int,
    ): Int {
        val length = readUInt32(bytes, offset).toInt()
        val nextOffset = offset + UINT32_SIZE_BYTES + length

        require(nextOffset <= bytes.size)
        return nextOffset
    }

    private fun readUInt32(
        bytes: ByteArray,
        offset: Int,
    ): Long {
        require(offset >= 0)
        require(offset + UINT32_SIZE_BYTES <= bytes.size)

        return ((bytes[offset].toLong() and 0xffL) shl 24) or
            ((bytes[offset + 1].toLong() and 0xffL) shl 16) or
            ((bytes[offset + 2].toLong() and 0xffL) shl 8) or
            (bytes[offset + 3].toLong() and 0xffL)
    }

    private fun writeUInt32(
        bytes: ByteArray,
        offset: Int,
        value: Long,
    ) {
        require(value in 0L..UINT32_MAX)
        require(offset >= 0)
        require(offset + UINT32_SIZE_BYTES <= bytes.size)

        bytes[offset] = (value ushr 24).toByte()
        bytes[offset + 1] = (value ushr 16).toByte()
        bytes[offset + 2] = (value ushr 8).toByte()
        bytes[offset + 3] = value.toByte()
    }

    private fun decode(encoded: String): ByteArray {
        return Base64.getDecoder().decode(encoded)
    }

    private const val UINT32_SIZE_BYTES: Int = 4
    private const val OPENSSH_AUTH_MAGIC_SIZE: Int = 15
    private const val PEM_LINE_LENGTH: Int = 64
    private const val UINT32_MAX: Long = 0xffff_ffffL
    private const val PEM_BOUNDARY_PREFIX: String = "-----"
    private const val PEM_BOUNDARY_SUFFIX: String = "-----"
    private const val OPENSSH_PRIVATE_KEY_LABEL: String = "OPENSSH PRIVATE KEY"

    private const val OPENSSH_ECDSA_UNENCRYPTED_BASE64: String =
        ""

    private const val OPENSSH_ED25519_UNENCRYPTED_BASE64: String =
        ""

    private const val OPENSSH_ED25519_ENCRYPTED_BASE64: String =
        ""

    private const val OPENSSH_RSA_UNENCRYPTED_BASE64: String =
        ""

    private const val OPENSSH_RSA_ENCRYPTED_BASE64: String =
        ""

    private const val PKCS8_RSA_UNENCRYPTED_BASE64: String =
        ""

    private const val PKCS8_RSA_ENCRYPTED_BASE64: String =
        ""
}
